import type { Metadata } from 'next';
import { notFound } from 'next/navigation';

import EnglishPage, { generateMetadata as englishMetadata } from '@/app/account-value/[tag]/page';
import { isIntlLocale } from '@/lib/i18n';
import { routePath, translateMetadata } from '@/lib/i18n-metadata';
import { setRequestLocale } from '@/lib/request-locale';

/* `/account-value/[tag]` in Spanish or Portuguese: the English page with the language set (see lib/i18n). Generated by scripts/i18n-wrappers.cjs. */
export const dynamic = 'force-dynamic';

type Props = { params: Promise<{ lang: string }> } & Record<string, unknown>;

async function language(props: Props) {
  const { lang } = await props.params;
  if (!isIntlLocale(lang)) notFound();
  setRequestLocale(lang);
  return lang;
}

export async function generateMetadata(props: Props): Promise<Metadata> {
  const lang = await language(props);
  const path = routePath('/account-value/[tag]', (await props.params) as Record<string, string | string[]>);
  return translateMetadata(await englishMetadata(props as never), lang, path);
}

export default async function IntlPage(props: Props) {
  await language(props);
  return EnglishPage(props as never);
}
